31	 * <pre>
32	 * &lt;untrusted_transcript_5f2c9a03d1b74e68&gt;
33	 * …the ingested text…
34	 * &lt;/untrusted_transcript_5f2c9a03d1b74e68&gt;
35	 * </pre>
36	 *
37	 * <p>The tag ends in a fresh {@link SecureRandom} nonce, generated per call and never reused, so
38	 * ingested text — written long before that nonce existed — cannot spell the closing marker whatever
39	 * lookalike it tries: {@code </untrusted-transcript>}, a zero-width space inside the word, or a
40	 * Cyrillic/fullwidth homoglyph all fail to match it. A guessable fence would be worse than none at
41	 * all here, because the prompts tell the model that the fenced region is data and the surrounding
42	 * message is instruction — so a forged close would promote attacker text to the instruction side.
43	 *
44	 * <p>Defence in depth, applied to the fenced text before it is wrapped: invisible format characters
45	 * (zero-width space/joiner, soft hyphen, BOM, the U+E00xx tag block) are dropped, other control and
46	 * line-separator characters collapse to spaces, and anything shaped like a fence marker is replaced
47	 * with a placeholder, so no lookalike marker reaches the model to confuse it. Replacing that shape
48	 * costs a little fidelity — a transcript that genuinely discusses "untrusted input" reaches the
49	 * model as "[marker removed]" — which is worth it for text that only ever feeds a prompt.
50	 *
51	 * <p>Unlike the miner's one-line evidence items, a transcript is legitimately multi-line and must
52	 * stay readable as one, so newlines and tabs are preserved on the way into a prompt. {@link
53	 * #fenced(String, String)} takes the tag as a parameter so any other untrusted prompt slot (the
54	 * miner's evidence block, say) can reuse the same unforgeable fence.
55	 */
56	final class UntrustedText {
57	
58	    private UntrustedText() {}
59	
60	    /** Fence tag for a raw transcript, or a digest rendered from one. */
61	    static final String TRANSCRIPT_TAG = "untrusted_transcript";
62	
63	    /** Fence tag for an AI analysis of a transcript, which inherits the transcript's taint. */
64	    static final String ANALYSIS_TAG = "untrusted_analysis";
65	
66	    /** What a fence lookalike found inside untrusted text is replaced with. */
67	    static final String MARKER_PLACEHOLDER = "[marker removed]";
68	
69	    /** 64 random bits per fence: far beyond guessing, and never reused across calls. */
70	    private static final int NONCE_BYTES = 8;
71	
72	    private static final SecureRandom NONCES = new SecureRandom();
73	
74	    /**
75	     * Anything shaped like a fence marker: the literal word however it is punctuated or spaced,
76	     * plus the word that follows it. Both quantifiers are possessive, so the match stays linear on
77	     * hostile input.
78	     */
79	    private static final Pattern FENCE_LOOKALIKE = Pattern.compile(
80	        "untrusted[\\p{Punct}\\s]*+\\w*+",
81	        Pattern.CASE_INSENSITIVE
82	    );
83	
84	    /** Fences an ingested transcript (or a digest rendered from one) for a prompt slot. */
85	    static String fencedTranscript(String text) {
86	        return fenced(TRANSCRIPT_TAG, text);
87	    }
88	
89	    /** Fences an AI analysis of an ingested transcript for a prompt slot. */
90	    static String fencedAnalysis(String text) {
91	        return fenced(ANALYSIS_TAG, text);
92	    }
93	
94	    /**
95	     * Wraps untrusted text in a fence whose tag ends in a fresh random nonce, after rendering the
96	     * text itself inert. The text is still passed through in full — only its ability to shape the
97	     * prompt around it is removed.
98	     */
99	    static String fenced(String tag, String text) {
100	        byte[] nonce = new byte[NONCE_BYTES];
101	        NONCES.nextBytes(nonce);
102	        String fenceTag = tag + "_" + HexFormat.of().formatHex(nonce);
103	        return "<" + fenceTag + ">\n" + inert(text) + "\n</" + fenceTag + ">";
104	    }
105	
106	    /**
107	     * Neutralizes an ingested value's ability to shape the prompt it is rendered into: fence
108	     * lookalikes are replaced, invisible format characters are dropped, and control characters other
109	     * than newline and tab collapse to spaces.
110	     */
111	    static String inert(String text) {
112	        if (text == null) return "";
113	        return FENCE_LOOKALIKE.matcher(scrub(text, true)).replaceAll(MARKER_PLACEHOLDER);
114	    }
115	
116	    /**
117	     * A single-line, length-capped rendering of one field of a model reply. The reply was produced
118	     * from an untrusted transcript, so a field must not be able to carry unbounded text, terminal
119	     * escapes, invisible characters, or forged line breaks into the store, the UI, and the miner
120	     * that later re-reads the recommendations as evidence. {@code null} stays {@code null}, so the
121	     * cached JSON keeps its shape.
122	     */
123	    static String boundedLine(String value, int max) {
124	        if (value == null) return null;
125	        return cap(scrub(value, false).replaceAll("\\s{2,}", " ").strip(), max);
126	    }
127	
128	    /** As {@link #boundedLine}, but for a paragraph field whose line breaks are worth keeping. */
129	    static String boundedText(String value, int max) {
130	        if (value == null) return null;
131	        return cap(scrub(value, true).strip(), max);
132	    }
133	
134	    private static String cap(String value, int max) {
135	        return value.length() > max ? value.substring(0, max) + "..." : value;
136	    }
137	
138	    /**
139	     * Drops the characters that are invisible to a human reading the text and replaces the ones that
140	     * could corrupt the structure it is rendered into with a space. Newlines and tabs are noise in a
141	     * one-line field but structure in a transcript or a paragraph, so {@code keepLineBreaks}
142	     * decides. Iterates by code point so supplementary invisibles (the U+E0000 tag block used to
143	     * smuggle hidden text) are covered too.
144	     */
145	    private static String scrub(String text, boolean keepLineBreaks) {
146	        StringBuilder out = new StringBuilder(text.length());
147	        int i = 0;
148	        while (i < text.length()) {
149	            int cp = text.codePointAt(i);
150	            i += Character.charCount(cp);
151	            if (keepLineBreaks && (cp == '\n' || cp == '\t')) {
152	                out.appendCodePoint(cp);
153	            } else if (Character.getType(cp) == Character.FORMAT) {
154	                // Zero-width space/joiner, soft hyphen, BOM, tag characters: invisible to a reader,
155	                // and enough to break a marker's spelling apart.
156	                continue;
157	            } else if (isStructural(cp)) {
158	                out.append(' ');
159	            } else {
160	                out.appendCodePoint(cp);
161	            }
162	        }
163	        return out.toString();
164	    }
165	
166	    /** True for characters that could forge a line — or a terminal escape — in the rendered text. */
167	    private static boolean isStructural(int cp) {
168	        int type = Character.getType(cp);
169	        return (
170	            Character.isISOControl(cp) ||
171	            type == Character.LINE_SEPARATOR ||
172	            type == Character.PARAGRAPH_SEPARATOR
173	        );
174	    }
175	}
