// Differential harness for the transcript scanner rewrite.
//
// Renders the same steps through the baseline renderer (today's main, with the size cap disabled so
// the scanners themselves are what gets compared) and through the candidate, then compares the
// resulting step-body HTML byte for byte. Both earlier attempts at this rewrite were rejected for
// missing a scanner site; the point here is to prove the *output* is unchanged while the cost shape
// changes, and to fail loudly on any divergence.
//
//   node diff.mjs <path-to-candidate-timeline.js> [caseCount]
//
// Exits non-zero on the first divergence, printing the input that caused it.

import { JSDOM } from "jsdom";
import { pathToFileURL } from "node:url";
import path from "node:path";

const candidatePath = process.argv[2];
const CASES = Number(process.argv[3] || 20000);
if (!candidatePath) {
  console.error("usage: node diff.mjs <candidate timeline.js> [caseCount]");
  process.exit(2);
}

const dom = new JSDOM("<!doctype html><body></body>", { url: "http://localhost" });
globalThis.window = dom.window;
globalThis.document = dom.window.document;
globalThis.performance = dom.window.performance;
globalThis.requestIdleCallback = undefined; // force the synchronous fill path

// marked/DOMPurify are loaded from a CDN by index.html; the renderer only needs *some* deterministic
// implementation for a byte-comparison, so stub them identically for both sides.
globalThis.marked = { parse: (t) => `<md>${t}</md>` };
globalThis.DOMPurify = { sanitize: (h) => h };

const here = path.dirname(new URL(import.meta.url).pathname);
const baseline = await import(pathToFileURL(path.join(here, "timeline.baseline.js")).href);
const candidate = await import(pathToFileURL(path.resolve(candidatePath)).href);

// Fragments chosen to exercise every construct the scanners look for, plus the shapes that broke
// earlier attempts: unclosed openings, distinct tag names, brackets inside mention names, bracketed
// link titles, and the four regex line terminators.
const FRAGMENTS = [
  "<ADDITIONAL_METADATA>", "</ADDITIONAL_METADATA>", "<USER_REQUEST>", "</USER_REQUEST>",
  "<A>", "</A>", "<AB>", "</AB>", "<lower>", "<A_B>", "</A_B>",
  "@[", "]", "@[f.txt]", " is a [File]:", "\n", "\r", "\r\n", " ", " ", "\t",
  "[1]", "[2]", "[12]", "[1] [t](http://e/x)", "[2] http://e/y", "](http://",
  "[3] [An [odd] title](http://e/z)", "plain words", "  ", "/tmp/a b.txt", "@[a[b]]",
  "http://e/q", "<", ">", "```", "*x*", "#h", "\\", "​", "﻿",
];

const STEP_TYPES = ["USER_INPUT", "PLANNER_RESPONSE", "MESSAGE", "SEARCH_WEB", "VIEW_FILE"];

// Deterministic PRNG so a failure is reproducible from the case index alone.
let seed = 0x2f6e2b1;
function rnd() {
  seed ^= seed << 13; seed >>>= 0;
  seed ^= seed >> 17;
  seed ^= seed << 5; seed >>>= 0;
  return seed / 0x100000000;
}

function mosaic() {
  const n = 1 + Math.floor(rnd() * 14);
  let s = "";
  for (let i = 0; i < n; i++) s += FRAGMENTS[Math.floor(rnd() * FRAGMENTS.length)];
  return s;
}

function render(mod, steps) {
  const container = document.createElement("div");
  document.body.replaceChildren(container);
  mod.renderTranscript(steps, container);
  // Bodies render on expansion; open every card so the scanner output is materialized.
  for (const h of container.querySelectorAll(".step-card .step-header")) h.click();
  return container.innerHTML;
}

let checked = 0;
for (let i = 0; i < CASES; i++) {
  const content = mosaic();
  for (const type of STEP_TYPES) {
    const steps = [
      { type, source: type === "USER_INPUT" ? "USER_EXPLICIT" : "MODEL",
        content, created_at: "2026-06-19T10:00:00Z" },
    ];
    const a = render(baseline, steps);
    const b = render(candidate, steps);
    checked++;
    if (a !== b) {
      console.error(`DIVERGENCE at case ${i}, step type ${type}`);
      console.error("input:  ", JSON.stringify(content));
      console.error("baseline:", JSON.stringify(a.slice(0, 400)));
      console.error("candidate:", JSON.stringify(b.slice(0, 400)));
      process.exit(1);
    }
  }
}
console.log(`${checked} render comparisons, 0 divergences`);

